-- PT115-S4-Q9. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT115-S4-Q9$batch03$ AND q.stimulus=$batch03$In each of the last ten years, there have been few complaints to law enforcement agencies of telemarketing fraud. Yet, in the last ten years, fraudulent telemarketing schemes have become a more and more serious problem, bilking victims out of millions of dollars annually.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to resolve the apparent conflict described above?$batch03$ AND q.correct_choice=$batch03$E$batch03$) THEN RAISE EXCEPTION 'Question changed: PT115-S4-Q9'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT115-S4-Q9$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT115-S4-Q9'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT115-S4-Q9$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$For ten years there have been few complaints of telemarketing fraud.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Telemarketing fraud has grown into a serious problem costing victims millions every year?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$Complaints are not the same as fraud. They count only victims who report. If most victims never complain, fraud can grow large while complaints stay low. Ask why a victim would stay quiet.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a reason victims of fraud do not complain.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT115-S4-Q9$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Punishment after conviction does not affect how many victims complain in the first place.$batch03$), ($batch03$B$batch03$, $batch03$This is about how hard complaints are to investigate. It says nothing about why there are so few complaints.$batch03$), ($batch03$C$batch03$, $batch03$Some schemes are discovered a year or two late. Over ten years, those victims would still eventually complain, and the choice covers only "some" schemes.$batch03$), ($batch03$D$batch03$, $batch03$Which court prosecutes the fraud does not explain why victims do not report it.$batch03$), ($batch03$E$batch03$, $batch03$Most victims are too embarrassed to seek any remedy, so they never complain. Fraud grows while complaints stay low.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT115-S4-Q9$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
